import {SIGMAS,LABELS,MAX_SCANS,site,confidence,sensorConfidence,train,createMission,observation,act,runMission,evaluate,traverse,best} from './engine.mjs?v=20261008r3';
import {pipeline,fusionLab,learningLab,advanceLab,resetLab,realism,cue} from './learning.mjs?v=20261008r3';
const app=document.querySelector('#app'), storageKey='rove-mission-v1';
let practiceSnapshot=null;
let mission=createMission(), practice=false, message='Your first scan is in. What’s your next move?', stage=0;
const competitionQ=train(.45), baselineEvaluation=evaluate(competitionQ);
let trainedPrice=.45;
let q=competitionQ, price=.45, scores=[], revealed=false, fuseIndex=0, fuseScans=1,fuseTruth=false;
let timerSeconds=180,timerRunning=false,timerHandle=null,trainingHandle=null,stormEvaluation=null,stormRecovery=null;
let evaluation=null, training=false, progress=0, checkpoints=[],stormActive=false,stormRetrained=false,stormQ=null;
let biasRepaired=false,biasEvaluation=null,labFocused=false;
try{const saved=JSON.parse(localStorage.getItem(storageKey));if(saved&&saved.seed===2047&&Array.isArray(saved.history)&&saved.history.length<=350){const restored=createMission();for(const entry of saved.history){if(!act(restored,entry.action).ok)throw Error('Invalid saved mission');}mission=restored;message='Your mission on this device has been restored.';}const host=JSON.parse(localStorage.getItem('rove-host-v1'));if(Array.isArray(host?.scores))scores=host.scores.filter(s=>typeof s.name==='string'&&Number.isFinite(s.liters));}catch{}
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pct=p=>Math.round(p*100), round=n=>Math.round(n), names={rove:'Rove · learned policy',always:'Always drill',fused:'Fuse, never rescan',expert:'Hand-tuned rule'};
const probText=p=>p>=.995?'>99':p<=.005?'<1':String(pct(p));
function toast(t){const e=document.querySelector('#toast');e.textContent=t;e.classList.add('visible');setTimeout(()=>e.classList.remove('visible'),2800);}
function save(){try{if(!practice)localStorage.setItem(storageKey,JSON.stringify(mission));localStorage.setItem('rove-host-v1',JSON.stringify({scores}));}catch{}}
const hostMode=()=>location.hash.startsWith('#console');
function layout(content){return `<header class="topbar"><a class="brand" href="#play" aria-label="Rove mission"><span class="mark" aria-hidden="true">+</span><span><span class="wordmark">ROVE</span><small>FUSE / DECIDE / FIGHT</small></span></a><nav class="nav" aria-label="Main navigation"><a href="#play" class="${!hostMode()?'active':''}">Play mission</a><a href="#console" class="${hostMode()?'active':''}">Presenter</a></nav><span class="top-meta">MARS FIELD OPERATIONS / 2047</span></header><main>${content}<footer class="footer"><span>FUSE, DECIDE, FIGHT &nbsp; / &nbsp; A workshop with Denisa Cakoni</span><span>Synthetic teaching mission · Fictional water score</span></footer></main>`;}
function sensors(readings){const p=confidence(readings),last=readings.at(-1);return `<div class="reading-block"><div class="confidence-head"><div class="confidence-num">${esc(probText(p))}<span>%</span></div><div class="confidence-caption">Model estimate<br>of a wet site</div></div><div class="confidence-bar" role="meter" aria-label="Estimated chance of water" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${pct(p)}"><span style="width:${pct(p)}%"></span></div><div class="scale"><span>LIKELY DRY</span><span>LIKELY WET</span></div><div class="sensors">${LABELS.map((name,i)=>`<div class="sensor"><div class="signal-label"><span>${name}<small>${[61,27,12][i]}% relative weight</small></span><span class="value mono">${esc(probText(sensorConfidence(last[i],i)))}%</span></div><div class="signal"><span style="width:${pct(sensorConfidence(last[i],i))}%"></span></div></div>`).join('')}</div></div>`;}
function stats(){return `<div class="stats"><div class="stat"><div class="stat-label">Water collected</div><div class="stat-value accent">${mission.liters}<span>L</span></div></div><div class="stat"><div class="stat-label">Battery remaining</div><div class="stat-value">${mission.battery}<span>/ 100</span></div><div class="battery-track"><div class="battery-fill" style="width:${mission.battery}%"></div></div></div><div class="stat"><div class="stat-label">${mission.done?'Sites visited':'Current site'}</div><div class="stat-value">${String(mission.index+(mission.done?0:1)).padStart(2,'0')}<span>/ traverse</span></div></div><div class="stat"><div class="stat-label">Successful drills</div><div class="stat-value">${mission.hits}<span>${mission.dry} dry ${mission.dry===1?'hole':'holes'}</span></div></div></div>`;}
function map(){const points=Array.from({length:7},(_,i)=>({x:64+i*82,y:150+Math.sin(i*1.9)*45}));return `<div class="terrain"><div class="terrain-top"><span>SURFACE SURVEY</span><span>SECTOR ${String(Math.floor(mission.index/7)+1).padStart(2,'0')}</span></div><svg class="map-svg" viewBox="0 0 640 300" role="img" aria-label="Traverse diagram. Current site ${mission.index+1}; dotted line shows the route ahead."><path d="${points.map((p,i)=>(i?'L':'M')+p.x+','+p.y).join(' ')}" fill="none" stroke="#d0b397" stroke-width="1.5" stroke-dasharray="5 7"/>${points.map((p,i)=>{const current=mission.index%7===i;return `${current?`<circle cx="${p.x}" cy="${p.y}" r="31" fill="#f5a36b14" stroke="#f5a36b55"/><circle cx="${p.x}" cy="${p.y}" r="20" fill="none" stroke="#f5a36b"/>`:''}<circle cx="${p.x}" cy="${p.y}" r="${current?6:4}" fill="${i<=mission.index%7?'#f5a36b':'#b4b8a5'}"/><text x="${p.x}" y="${p.y+48}" fill="#e7dfce" text-anchor="middle" font-family="monospace" font-size="11">${String(Math.floor(mission.index/7)*7+i+1).padStart(2,'0')}</text>`}).join('')}</svg><div class="location"><h2>AEOLIS TRAVERSE</h2><p>${practice?'PRACTICE':'MSN-2047'} / SITE ${String(mission.index+1).padStart(2,'0')}</p></div><div class="map-key"><span>◉</span> YOUR POSITION</div></div>`;}
function logView(history=mission.history){return `<div class="log">${history.length?history.slice(-12).reverse().map(e=>`<div class="log-row"><span><small>${String(e.site).padStart(2,'0')}</small> &nbsp; ${e.action==='scan'?'Additional scan':e.action==='move'?'Moved on':e.wet?'Water found':'Dry hole'}</span><span>${e.liters?`<b>+${e.liters} L</b> &nbsp; `:''}<small>${e.battery} BAT</small></span></div>`).join(''):'<div class="empty">Your decisions will appear here.</div>'}</div>`;}
function help(){return `<details class="help"><summary>Mission briefing & how it works</summary><div class="help-grid"><div><p><strong>Your goal:</strong> collect as much water as you can with 100 battery. Every site starts with one free reading from three noisy sensors.</p><p><strong>Scan again:</strong> spend 1 battery for more evidence. <strong>Drill:</strong> spend 9 (6 to drill + 3 to travel), collect any water, and move on. <strong>Move on:</strong> spend 3 and skip the site. Up to 8 additional scans per site.</p></div><div><p>30% of synthetic sites contain 40–120 liters. Sensor weights reflect their noise. The large percentage combines all readings so far; the smaller percentages use each sensor’s latest reading.</p><p>Everyone on MSN-2047 gets the same sites and scan sequences. Your decisions change your route length. Progress is saved on this device. Send your final liters in Zoom chat; scores are entered by the presenter.</p></div></div></details>`;}
function play(){const last=mission.history.at(-1);const o=mission.done&&last?{readings:[site(mission.seed,Math.max(0,last.site-1),mission.storm).scans[0]]}:observation(mission);return `<div class="page-head"><div><div class="eyebrow">${practice?'TRAINING GROUND':'MISSION 2047'} / HUMAN PILOT</div><h1>Make every scan count.</h1><p>Find water. Spend wisely. Can you beat Rove?</p><p class="compact">A simulated mission for learning sensor fusion and reinforcement learning.</p></div><div class="toolbar"><span class="chip orange">${practice?'PRACTICE RUN':'SHARED MISSION'}</span><button class="small ghost" data-do="practice">${practice?'Return to mission':'Try practice'}</button></div></div>${stats()}<div class="mission-grid"><div><section class="panel">${mission.done?`<div class="result"><div class="eyebrow">MISSION COMPLETE</div><h2>You made the calls.</h2><div class="big">${mission.liters}<span style="font-size:35px"> L</span></div><p>${mission.hits} water sites · ${mission.dry} dry holes · ${mission.totalScans} extra scans.<br>${practice?'Practice complete. Ready for the shared mission?':'Post your liters in Zoom chat. Your presenter will reveal Rove’s result.'}</p><div class="toolbar"><button class="primary" data-do="copy-score">Copy my score</button><button data-do="${practice?'practice':'restart'}">${practice?'Play MSN-2047':'Replay mission'}</button></div></div>`:`${map()}<div class="decision"><div class="decision-top"><div><h3>What’s your next move?</h3><p>More evidence, or time to commit?</p></div><span class="chip">SCAN ${mission.rescans+1}</span></div><div class="actions"><button class="action" data-action="scan" ${mission.battery<4||mission.rescans>=MAX_SCANS?'disabled':''}><strong>Scan again <kbd>S</kbd></strong><small>−1 BATTERY</small></button><button class="action primary" data-action="drill" ${mission.battery<9?'disabled':''}><strong>Drill here <kbd>D</kbd></strong><small>−9 BATTERY</small></button><button class="action" data-action="move" ${mission.battery<3?'disabled':''}><strong>Move on <kbd>M</kbd></strong><small>−3 BATTERY</small></button></div><div class="feedback">${esc(message)}</div>${mission.battery<9?'<p class="compact muted">Not enough battery to drill. Move on to finish your traverse.</p>':''}</div>`}</section><section class="panel section-gap"><div class="panel-head"><h3>Mission log</h3><span class="eyebrow">RECENT ACTIVITY</span></div>${logView()}</section></div><aside class="panel telemetry"><div class="panel-head"><h3>${mission.done?'Final observation':'Sensor fusion'}</h3><span class="chip">${mission.done?'INITIAL SCAN AT LAST SITE':(mission.rescans+1)+' '+(mission.rescans?'READINGS':'READING')}</span></div>${sensors(o.readings)}<div class="note"><strong>Evidence first. Decision next.</strong><br>This percentage comes from sensor fusion. Rove’s learned policy uses it to choose an action. Liters are a fictional resource score.</div></aside></div>${help()}${!mission.done?`<details class="help"><summary>Trace my sensor estimate</summary>${fusionLab(o.readings)}</details>`:''}${realism()}`;}
function presenter(){return `<div class="page-head"><div><div class="eyebrow">PRESENTER CONSOLE / 60-MINUTE WORKSHOP</div><h1>Fuse. Decide. Fight.</h1><p>From noisy evidence to a learned decision. Open the code and test what changes.</p></div><div class="toolbar"><a class="button-link small" href="./script.html" target="_blank" rel="noopener">Workshop script ↗</a><button class="small" data-do="copy-link">Copy participant link</button></div></div>${pipeline()}<nav class="stage-nav" aria-label="Workshop stages">${['Fuse','Decide','Inside','Fight','Break'].map((s,i)=>`<button data-stage="${i}" class="${stage===i?'active':''}" aria-current="${stage===i?'step':'false'}"><span>0${i+1} / ${['04–14','14–27','27–33','33–47','47–53'][i]} MIN</span>${s}</button>`).join('')}</nav>${cue(stage)}<div id="stage-content">${stageView()}${stage===0?fusionLab(site(3105,fuseIndex).scans.slice(0,fuseScans)):stage===1?learningLab(labFocused):''}</div>${realism()}<div class="footer"><span>← → stages · Space: next training checkpoint</span><span>Presenter controls and chat scores are local to this device.</span></div>`;}
function heading(k,title){return `<div class="step-title"><div class="eyebrow">${k}</div><h2>${title}</h2></div>`;}
function policyStrip(model=q,k=0){return `<div class="policy" aria-label="Preferred actions across 18 water-confidence bins">${Array.from({length:18},(_,i)=>{const a=best(model,(i+.5)/18,k);return `<span class="a${a}" title="${Math.round(i/18*100)}–${Math.round((i+1)/18*100)}%: ${['scan','drill','move'][a]}">${['S','D','M'][a]}</span>`}).join('')}</div><div class="scale"><span>0% WATER</span><span>100% WATER</span></div>`;}
function bars(rows,unit='L',max=500){return rows.map(r=>`<div class="bar-row ${r.featured?'featured':''}"><span>${r.name}</span><div class="bar"><span style="width:${Math.min(100,r.value/max*100)}%"></span></div><strong>${Math.round(r.value)}${unit==='%'?'%':' '+unit}</strong></div>`).join('');}
function learningChart(){const shown=checkpoints.slice(0,progress);const values=shown.map(x=>x.liters);const max=500;return `<svg class="chart" viewBox="0 0 620 240" role="img" aria-label="Learning curve. Mean liters across 60 fixed evaluation missions at each training checkpoint.">${[0,100,200,300,400,500].map(v=>`<line x1="45" y1="${210-v/max*185}" x2="600" y2="${210-v/max*185}" stroke="#343b35"/><text x="32" y="${214-v/max*185}" text-anchor="end" fill="#b1b9b4" font-family="monospace" font-size="11">${v}</text>`).join('')}<text x="45" y="237" fill="#b1b9b4" font-family="monospace" font-size="11">0 SITES</text><text x="600" y="237" text-anchor="end" fill="#b1b9b4" font-family="monospace" font-size="11">8,000 SITES</text><path d="${values.map((v,i)=>(i?'L':'M')+(45+(i+1)/8*550)+','+(210-v/max*185)).join(' ')}" fill="none" stroke="#f5a36b" stroke-width="3"/>${values.map((v,i)=>`<circle cx="${45+(i+1)/8*550}" cy="${210-v/max*185}" r="4" fill="#f5a36b"/>`).join('')}${!values.length?'<text x="325" y="120" text-anchor="middle" fill="#b1b9b4" font-size="15">Train Rove to reveal the learning curve.</text>':''}</svg>`;}
function stageView(){
 if(stage===0){const s=site(3105,fuseIndex),readings=s.scans.slice(0,fuseScans),accuracy=traverse();return `<div class="host-grid"><div><section class="panel"><div class="panel-head"><h3>Site scanner</h3><span class="chip">DEMO ${String(fuseIndex+1).padStart(2,'0')} / ${fuseScans} ${fuseScans===1?'SCAN':'SCANS'}</span></div>${sensors(readings)}<div class="pad" style="padding-top:0"><div class="toolbar"><button class="primary" data-do="fuse-scan" ${fuseScans>MAX_SCANS?'disabled':''}>Scan again</button><button data-do="fuse-reveal" ${fuseTruth?'disabled':''}>Reveal truth</button><button class="ghost" data-do="fuse-next">Next site →</button></div>${fuseTruth?`<div class="callout">${s.wet?`Water found: ${s.liters} liters.`:'This site is dry.'} The estimate was ${esc(probText(confidence(readings)))}%.</div>`:''}</div></section><div class="callout">Ask the room: “Wet or dry? Which instrument would you trust—and why?”</div></div><aside><section class="panel pad">${heading('01 / FUSE','Three different views.')}<p>Each instrument has noise. The most reliable reading gets the most weight. Every new scan adds evidence.</p>${bars([...LABELS.map((name,i)=>({name,value:accuracy[i]})),{name:'Fused · one scan',value:accuracy[3],featured:true},{name:'Fused · three scans',value:accuracy[4],featured:true}],'%',100)}<p class="compact">Accuracy over 4,000 synthetic sites. Always guessing “dry” has an expected accuracy of 70% because only 30% of sites contain water.</p></section></aside></div>`;}
 if(stage===1){const shown=progress?checkpoints[progress-1]:null;return `<div class="host-grid"><section class="panel"><div class="panel-head"><h3>Learning to spend information wisely</h3><span class="chip">${(progress*1000).toLocaleString()} / 8,000 SITES</span></div><div class="pad"><div class="eyebrow">MEAN WATER COLLECTED / LITERS</div>${learningChart()}<div class="progress"><span style="width:${progress/8*100}%"></span></div><div class="toolbar"><button class="primary" data-do="train" ${training?'disabled':''}>${training?'Reviewing checkpoints…':progress?'Train again':'Train Rove'}</button><button data-do="next-checkpoint" ${!training?'disabled':''}>Next checkpoint</button><button class="ghost" data-do="fast-train" ${!training?'disabled':''}>Show final policy</button></div><p class="status-line">${training?'Training has finished in this browser. Reveal the measured checkpoints one at a time.':progress?'8,000 practice sites completed. Results are computed from the learned policy.':'Start with a blank action-value table. Watch the decisions emerge.'}</p>${shown?`<div class="section-gap"><h3>Policy after the first reading</h3>${policyStrip(shown.q)}<div class="legend"><span><b>M</b> Move on</span><span><b>S</b> Scan again</span><span><b>D</b> Drill</span></div></div>`:''}</div></section><aside><section class="panel pad">${heading('02 / DECIDE','What is a scan worth?')}<p>Rove tries actions, gets a reward, and updates its table. We specify the costs; it learns which action to take.</p><label for="price">Battery price <strong class="mono" id="price-value">${price.toFixed(2)}</strong></label><input id="price" type="range" min="0.1" max="1.3" step="0.05" value="${price}" ${training?'disabled':''}><div class="scale"><span>CHEAP TO EXPLORE</span><span>COSTLY TO ACT</span></div><p class="compact">Change the price, predict the effect, then press Train Rove. Current learned policy: price ${trainedPrice.toFixed(2)}. Shared mission Rove always uses 0.45.</p><div class="callout">Reward = +10 for finding water − the battery price × battery spent.</div><p class="compact">Exploration falls from 100% to 3%. The graph uses 60 separate, fixed test missions at each checkpoint. Learning can be uneven.</p></section></aside></div>`;}
 if(stage===2){evaluation=evaluation||evaluate(q);return `<section class="panel"><div class="pad">${heading('03 / INSIDE','Open the black box.')}<p>Each cell shows the preferred action at a confidence level. Rows track how many additional scans have been used.</p>${[0,1,2,3].map(k=>`<div class="section-gap"><div class="eyebrow">${k} ADDITIONAL SCANS</div>${policyStrip(q,k)}</div>`).join('')}<div class="legend"><span><b>M</b> Move on</span><span><b>S</b> Scan again</span><span><b>D</b> Drill</span><span>Trained battery price ${trainedPrice.toFixed(2)}</span></div></div><div class="table-wrap"><table><thead><tr><th>Strategy</th><th>Water / mission</th><th>Water hits / mission</th><th>Dry holes / mission</th><th>Extra scans / mission</th></tr></thead><tbody>${evaluation.map(r=>`<tr class="${r.policy==='rove'?'featured':''}"><td>${names[r.policy]}</td><td>${round(r.liters)} L</td><td>${r.hits.toFixed(2)}</td><td>${r.dry.toFixed(2)}</td><td>${r.scans.toFixed(1)}</td></tr>`).join('')}</tbody></table></div><div class="note">300 fixed evaluation missions, separate from training. These are measured averages, not guaranteed outcomes. The hand-tuned rule is a useful comparison; it can outperform the learned policy.</div></section><details class="help"><summary>What exactly is Rove learning?</summary><p>Tabular Q-learning over 18 confidence bins × 9 scan-count states × 3 actions. Sensor readings are independent Gaussian draws conditional on wet/dry ground; the fused estimate updates prior odds of 30% using all observations. Noise standard deviations: 1.56, 2.34, 3.51.</p><p>The training reward is +10 per water discovery, minus action costs at the selected price. Water volume is independently sampled from 40–120 L and is unknown before drilling, so each discovery has the same expected volume. Rove learns a cost-sensitive per-site policy; it does not plan the exact remaining mission battery. At play time, unaffordable actions are replaced by moving on.</p><p>In the hand-tuned rule, drill above 68%, move below 18%, otherwise scan up to three extra times. The shared challenge uses the fixed 0.45-price policy regardless of your demonstrations.</p></details>`;}
 if(stage===3){const result=runMission(2047,'rove',competitionQ),comparisons=['rove','always','fused','expert'].map(policy=>({name:names[policy].split(' ·')[0],value:runMission(2047,policy,competitionQ).liters,featured:policy==='rove'}));return `<div class="host-grid"><div><section class="panel pad">${heading('04 / FIGHT','The room vs. Rove.')}<p>Share the participant link. Everyone plays MSN-2047 with 100 battery, the same sites, and the same readings. Ask for final liters in Zoom chat.</p><div class="toolbar"><button data-do="copy-link">Copy participant link</button><button data-do="timer">${timerRunning?'Pause timer':'Start 3-minute timer'}</button><span class="mono" id="countdown">${timerText()}</span></div><form id="score-form"><div class="fields"><div class="field"><label for="score-name">Name (optional)</label><input id="score-name" maxlength="40" placeholder="Pilot ${scores.length+1}" autocomplete="off"></div><div class="field"><label for="score-liters">Liters from chat</label><input id="score-liters" type="number" min="0" max="1320" step="1" required placeholder="390"></div><button class="primary" type="submit">Add score</button></div></form><div class="toolbar"><span class="chip">${scores.length} SCORES</span><button class="small ghost" data-do="undo" ${!scores.length?'disabled':''}>Undo last</button><button class="small ghost" data-do="clear-scores" ${!scores.length?'disabled':''}>Clear rehearsal</button></div><ul class="score-list">${scores.length?[...scores].sort((a,b)=>b.liters-a.liters).map((s,i)=>`<li><span><span class="muted mono">${String(i+1).padStart(2,'0')}</span> &nbsp; ${esc(s.name)}</span><strong>${s.liters} L</strong></li>`).join(''):'<li class="muted">Waiting for the room’s scores.</li>'}</ul></section>${revealed?`<section class="panel section-gap"><div class="panel-head"><h3>Rove’s mission replay</h3><span class="chip">${result.index} SITES VISITED</span></div><div class="table-wrap"><table><thead><tr><th>Site</th><th>Water estimate</th><th>Decision</th><th>Outcome</th></tr></thead><tbody>${result.history.map(e=>`<tr><td>${e.site}</td><td>${esc(probText(e.p))}%</td><td>${{scan:'Scan again',move:'Move on',drill:'Drill'}[e.action]}</td><td>${e.action==='scan'?'More evidence':e.action==='move'?'Unobserved':e.wet?'+'+e.liters+' L':'Dry hole'}</td></tr>`).join('')}</tbody></table></div></section>`:''}</div><aside><section class="panel"><div class="panel-head"><h3>Rove’s sealed result</h3><span class="chip">MSN-2047</span></div>${revealed?`<div class="result"><div class="eyebrow">STANDARD POLICY / PRICE 0.45</div><div class="big">${result.liters}<span style="font-size:35px"> L</span></div><p>${result.hits} water sites · ${result.dry} dry holes<br>${result.totalScans} extra scans · ${result.index} sites visited</p><p>${scores.length?`${scores.filter(s=>s.liters>result.liters).length} pilots beat Rove. ${scores.filter(s=>s.liters===result.liters).length} tied.`:'Add the room’s scores to compare.'}</p><button class="ghost small" data-do="hide-result">Seal again</button></div>`:`<div class="score-locked"><div class="lock">?</div><p>Collect the room’s scores.<br>Then open the envelope.</p><button class="primary section-gap" data-do="reveal-result">Reveal Rove</button></div>`}</section>${revealed?`<section class="panel pad section-gap"><h3>Same map. Different choices.</h3>${bars(comparisons,'L',Math.max(...comparisons.map(r=>r.value),1))}</section>`:''}<div class="callout">One mission includes luck. Ask: “Which decision would you change if you could play again?”</div></aside></div>`;}
 const normal=baselineEvaluation[0],failed=stormActive?stormEvaluation[0]:null,recovered=stormRetrained?stormRecovery[0]:null;const dry=site(2047,1,stormActive),p=confidence([dry.scans[0]]);return `<div class="host-grid"><div><section class="panel ${stormActive?'storm-panel':''}"><div class="panel-head"><h3>A dry site, ${stormActive?'inside the storm':'under clear skies'}</h3><span class="chip orange">GROUND TRUTH: DRY</span></div>${sensors([dry.scans[0]])}<div class="pad" style="padding-top:0"><div class="toolbar"><button class="primary" data-do="storm">${stormActive?'Reset to clear skies':'Start the dust storm'}</button><button data-do="storm-retrain" ${!stormActive||stormRetrained?'disabled':''}>${stormRetrained?'Retrained in storm':'Retrain in the storm'}</button><button data-do="bias-repair" ${!stormActive?'disabled':''}>${biasRepaired?'Hide known-bias repair':'Test a known-bias repair'}</button></div></div>${biasRepaired?`<div class="pad repair-panel"><div class="eyebrow">MODEL REPAIR · KNOWN OFFSET</div><h3>Subtract 2.6 before fusing.</h3><div class="repair-values"><span>${pct(p)}%<small>Uncorrected</small></span><b>→</b><span>${(confidence([dry.scans[0]],2.6)*100).toFixed(1)}%<small>Bias corrected</small></span></div><p class="compact">In this controlled experiment we know the exact offset. Subtracting it restores the original observations and the original policy’s ${Math.round(biasEvaluation[0].liters)} L measured average across the same 300 missions. In deployment, estimating that offset is a separate problem.</p>${fusionLab(dry.scans.slice(0,1).map(scan=>scan.map(value=>value-2.6)))}</div>`:''}<div class="note">The storm adds the same +2.6 offset to every instrument. Fusion still assumes clear skies, so its displayed ${pct(p)}% is ${stormActive?'miscalibrated':'based on the original model'}.</div></section><section class="panel pad section-gap"><h3>What happens across 300 missions?</h3>${bars([{name:'Clear skies',value:normal.liters,featured:true},...(failed?[{name:'Storm · original',value:failed.liters}]:[]),...(recovered?[{name:'Storm · retrained',value:recovered.liters,featured:true}]:[])],'L',450)}<div class="table-wrap"><table><thead><tr><th>Condition</th><th>Dry holes / mission</th><th>Water hits / mission</th></tr></thead><tbody><tr><td>Clear skies</td><td>${normal.dry.toFixed(2)}</td><td>${normal.hits.toFixed(2)}</td></tr>${failed?`<tr><td>Storm · original</td><td>${failed.dry.toFixed(2)}</td><td>${failed.hits.toFixed(2)}</td></tr>`:''}${recovered?`<tr><td>Storm · retrained</td><td>${recovered.dry.toFixed(2)}</td><td>${recovered.hits.toFixed(2)}</td></tr>`:''}</tbody></table></div></section></div><aside class="panel pad">${heading('05 / BREAK','Agreement isn’t certainty.')}<p class="question">Would a fourth sensor save us?</p><p>Ask the room to predict before starting the storm. All three instruments share a bias. More agreeing readings can strengthen a wrong estimate.</p><div class="callout">Fusion can handle correlated errors—if its model accounts for them. This model does not account for the storm.</div><p>Retraining changes the decisions, but the fused percentages remain miscalibrated. Better repairs include detecting the shift, correcting the bias, or adding an instrument that fails differently.</p><p class="compact">Wrap up: combine evidence, learn when information is worth its cost, and test how the system fails.</p></aside></div>`;
}

function render(){document.body.classList.toggle('lab-focused',labFocused&&hostMode()&&stage===1);const focusedControl=document.activeElement?.dataset?.do,focusedId=document.activeElement?.id;const opened=new Set([...app.querySelectorAll('details[open]')].map(d=>d.querySelector('summary')?.textContent));app.innerHTML=layout(hostMode()?presenter():play());for(const d of app.querySelectorAll('details'))if(opened.has(d.querySelector('summary')?.textContent))d.open=true;if(labFocused&&hostMode()&&stage===1)app.querySelector('.lab-code details').open=true;if(focusedControl)app.querySelector(`[data-do="${focusedControl}"]`)?.focus({preventScroll:true});else if(focusedId)document.getElementById(focusedId)?.focus({preventScroll:true});}
function takeAction(a){const previous=mission.done?null:observation(mission).p;const result=act(mission,a);if(result.ok&&a==='scan')result.message=`Scan received: ${probText(previous)}% → ${probText(observation(mission).p)}% estimated wet. New evidence can raise or lower confidence.`;if(!result.ok)return result;message=result.message;save();render();document.querySelector('#announcer').textContent=message+(mission.done?' Mission complete. '+mission.liters+' liters collected.':' Battery: '+mission.battery+'. Water estimate: '+probText(observation(mission).p)+' percent.');return result;}
async function copy(t){try{await navigator.clipboard.writeText(t);toast('Copied to clipboard.');}catch{toast('Copy unavailable. Select and copy the text on screen.');}}
app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.action){takeAction(b.dataset.action);return;}if(b.dataset.stage){stage=Number(b.dataset.stage);render();return;}const a=b.dataset.do;if(a==='practice'){if(!practice){save();practiceSnapshot=mission;}practice=!practice;if(practice)mission=createMission(4815);else mission=practiceSnapshot||createMission();message=practice?'Practice is separate from the shared mission. Try a decision.':'Back on the shared mission.';render();}if(a==='restart'){if(confirm('Replay the same mission? This replaces your saved run on this device.')){mission=createMission();message='A fresh run on the same map.';save();render();}}if(a==='copy-score')copy(`${practice?'Practice':'MSN-2047'}: ${mission.liters} L · ${mission.hits} water sites · ${mission.dry} dry holes`);if(a==='copy-link')copy(location.href.split('#')[0]+'#play');});

function timerText(){return Math.floor(timerSeconds/60)+':'+String(timerSeconds%60).padStart(2,'0');}
function finishTraining(){clearInterval(trainingHandle);progress=8;training=false;evaluation=null;render();}
function startTraining(){if(training)return;training=true;progress=0;checkpoints=[];evaluation=null;trainedPrice=price;q=train(trainedPrice,false,(n,model)=>{const performance=evaluate(model,false,60)[0];checkpoints.push({q:model,liters:performance.liters});});progress=1;render();}
function nextCheckpoint(){if(!training)return;progress++;if(progress>=8)finishTraining();else render();}
app.addEventListener('input',e=>{if(e.target.id==='price'){price=Number(e.target.value);document.querySelector('#price-value').textContent=price.toFixed(2);}});
app.addEventListener('change',e=>{if(e.target.id==='price'){progress=0;checkpoints=[];render();}});
app.addEventListener('submit',e=>{if(e.target.id!=='score-form')return;e.preventDefault();const input=document.querySelector('#score-liters'),liters=Number(input.value),name=document.querySelector('#score-name').value.trim()||'Pilot '+(scores.length+1);if(!Number.isInteger(liters)||liters<0||liters>1320){toast('Enter a whole number from 0 to 1,320 liters.');return;}scores.push({name:name.slice(0,40),liters});save();render();document.querySelector('#score-liters')?.focus();});
app.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;const a=b.dataset.do;if(a==='fuse-scan'){fuseScans=Math.min(MAX_SCANS+1,fuseScans+1);fuseTruth=false;render();}if(a==='fuse-reveal'){fuseTruth=true;render();}if(a==='fuse-next'){fuseIndex++;fuseScans=1;fuseTruth=false;render();}if(a==='lab-focus'){labFocused=!labFocused;render();}if(a==='lab-step'){advanceLab();render();}if(a==='lab-batch'){advanceLab(25);render();}if(a==='lab-reset'){resetLab();render();}if(a==='bias-repair'){biasRepaired=!biasRepaired;if(biasRepaired&&!biasEvaluation)biasEvaluation=evaluate(competitionQ,true,300,2.6);render();}if(a==='next-checkpoint')nextCheckpoint();if(a==='train')startTraining();if(a==='fast-train')finishTraining();if(a==='undo'){scores.pop();save();render();}if(a==='clear-scores'&&confirm('Clear all rehearsal scores stored on this device?')){scores=[];revealed=false;save();render();}if(a==='reveal-result'){revealed=true;render();}if(a==='hide-result'){revealed=false;render();}if(a==='timer'){if(timerRunning){clearInterval(timerHandle);timerRunning=false;}else{if(timerSeconds<=0)timerSeconds=180;timerRunning=true;timerHandle=setInterval(()=>{timerSeconds--;const t=document.querySelector('#countdown');if(t)t.textContent=timerText();if(timerSeconds<=0){clearInterval(timerHandle);timerRunning=false;toast('Time to post your liters in chat.');render();}},1000);}render();}if(a==='storm'){stormActive=!stormActive;stormRetrained=false;biasRepaired=false;if(stormActive&&!stormEvaluation)stormEvaluation=evaluate(competitionQ,true);render();}if(a==='storm-retrain'&&stormActive){stormQ=stormQ||train(.45,true);stormRecovery=stormRecovery||evaluate(stormQ,true);stormRetrained=true;render();}});
window.addEventListener('hashchange',render);
window.addEventListener('keydown',e=>{if(e.target.closest('input,textarea,select,button,summary')||e.ctrlKey||e.metaKey||e.altKey||e.repeat)return;if(hostMode()){if(e.code==='Space'&&training){e.preventDefault();nextCheckpoint();}if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();stage=Math.max(0,Math.min(4,stage+(e.key==='ArrowRight'?1:-1)));render();}}else{const a={s:'scan',d:'drill',m:'move'}[e.key.toLowerCase()];if(a){e.preventDefault();takeAction(a);}}});
render();

// Optional agent interface: uses the same mission state and action validation as the UI.
const webContext=document.modelContext;
if(webContext?.registerTool){const lifecycle=new AbortController();const state=()=>({mode:practice?'practice':'shared',site:mission.index+1,battery:mission.battery,liters:mission.liters,done:mission.done,waterProbability:observation(mission).p});const definitions=[{name:'read_rover_mission',title:'Read rover mission',description:'Read the current participant mission, battery, water collected and fused estimate. Does not reveal underground truth.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(input&&Object.keys(input).length)throw Error('No input fields expected.');return state();}},{name:'take_rover_action',title:'Take a rover action',description:'Spend battery to scan, drill, or move in the current participant mission. Updates the visible game and saved progress.',inputSchema:{type:'object',properties:{action:{type:'string',enum:['scan','drill','move']}},required:['action'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||Object.keys(input).some(k=>k!=='action')||!['scan','drill','move'].includes(input.action))throw Error('Choose scan, drill, or move.');if(hostMode())throw Error('Open Play mission before taking a participant action.');const result=takeAction(input.action);if(!result.ok)throw Error(result.message);return {...state(),message:result.message};}}];for(const tool of definitions){try{Promise.resolve(webContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});}
